import{_ as o,o as a,c as t,a2 as i}from"./chunks/framework.DAT6-Kny.js";const g=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),d={name:"changelog.md"};function n(r,e,c,l,s,h){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to this project will be documented in this file.</p><p>The format is based on <a href="https://keepachangelog.com/en/1.0.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and this project adheres to <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><h2 id="_0-2-3-2026-09-xx" tabindex="-1">[0.2.3] - 2026-09-XX <a class="header-anchor" href="#_0-2-3-2026-09-xx" aria-label="Permalink to &quot;[0.2.3] - 2026-09-XX&quot;">​</a></h2><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>PKCE silent token errors</strong> — <code>PKCEAuthStrategy.getToken()</code> and <code>refreshToken()</code> match cc-widget <code>auth.ts</code> on silent SSO failure: <code>InteractionRequiredAuthError</code> falls back to <code>authenticate()</code> (popup) or <code>acquireTokenRedirect</code> (redirect); <code>monitor_window_timeout</code> falls back to <code>acquireTokenPopup</code>. <code>authenticate()</code> always runs interactive login (<code>loginPopup</code> / <code>loginRedirect</code>); <code>AiAgent</code> skips it when initialize already restored a session. Previously those errors were rethrown or a stale token was returned, which aborted portal init in embedded hosts such as Genesys.</li><li><strong>PKCE popup authentication</strong> — <code>PKCEAuthStrategy</code> omits <code>nextRoute</code> and OAuth <code>state</code> when <code>authScheme</code> is <code>popup</code>, matching legacy cc-widget <code>auth.ts</code> behavior. Prevents <code>auth-redirect.html</code> from bouncing the MSAL popup to the app URL and triggering MSAL <code>block_nested_popups</code> during cc-widget bootstrap. Redirect flow is unchanged (<code>state</code> still carries the return URL).</li><li><strong>Auth token propagation</strong> — new <code>finishAuthentication</code> callback syncs the access token from the active auth strategy via <code>AuthenticationService.getToken()</code> before <code>onAuthComplete</code>, fixing cases where strategy callbacks supplied tokens that were not cached in <code>AuthenticationService</code> (e.g. anonymous → PKCE switch, anonymous agents, and <code>restartPortalInitializer()</code>)</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong><code>HookContract.getMsalAccessToken()</code></strong> — returns only the cached token synchronously; removed fire-and-forget <code>getToken()</code> side effect (use <code>getAccessToken()</code> when a fresh token is required)</li></ul><h2 id="_0-2-2-2026-08-21" tabindex="-1">[0.2.2] - 2026-08-21 <a class="header-anchor" href="#_0-2-2-2026-08-21" aria-label="Permalink to &quot;[0.2.2] - 2026-08-21&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Session creation with context</strong> — <code>ApiHelper.getAiAgentSession()</code> uses <code>POST .../session</code> with an optional <code>{ context }</code> body (falls back to <code>GET</code> on 403/404/405); <code>AiAgent</code> passes stored context when creating or restarting sessions, including <code>egain_portal_id</code> from the last selected portal when present</li><li><strong><code>contextValidation</code> agent event</strong> — emitted when the platform returns a non-terminal system message for rejected context attributes (without ending the session)</li><li><strong><code>ContextValidationHandler</code></strong> and exported type <strong><code>ContextValidationIssue</code></strong> for custom message pipelines</li><li><strong><code>MessageData.escalationData</code></strong> — optional <code>liveDomain</code> and <code>entrypointUrl</code> on inbound escalation payloads (Advisor Desktop chat transfer)</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong><code>setContext()</code></strong> — merges into cached context; <code>sendImmediately</code> sends only attribute values that changed since the last stored context</li><li><strong><code>restartConnection()</code></strong> — new sessions receive context via the session POST; WebSocket <code>sendStoredContext()</code> runs only when the caller supplies an existing <code>sessionId</code> (compatibility path)</li><li><strong><code>cache.enabled: false</code></strong> — disables deployment-info static cache, portal pipeline profile cache (<code>pipelineCache</code>), and uses a memory-only context adapter (no session/local persistence)</li></ul><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong><code>pipelineCache</code></strong> and <strong><code>getDeploymentInfo</code></strong> now honor <code>cache.enabled: false</code> instead of still reading or writing cached deployment info and profile lists</li><li><strong>Customer <code>getPortals</code> failures</strong> — portal-trained self-service agents (<code>userType: customer</code> with configured <code>portals</code>) now reject <code>initialize()</code> with <code>InitializationPipelineError</code> (<code>PORTAL_FETCH_FAILED</code>) when the portalmgr API fails, matching the <code>getMyPortals</code> path so hosts can surface errors instead of staying in a loading state</li><li><strong>Session ID validation</strong> — <code>getSessionId()</code>, <code>getWsEndpoint()</code>, and <code>ApiHelper.getAiAgentSession()</code> reject placeholder or missing session ids (<code>undefined</code>, <code>null</code>, blank strings) before constructing the chat WebSocket URL; the query parameter is set via <code>URLSearchParams</code> instead of string interpolation</li></ul><h2 id="_0-2-1-2026-07-30" tabindex="-1">[0.2.1] - 2026-07-30 <a class="header-anchor" href="#_0-2-1-2026-07-30" aria-label="Permalink to &quot;[0.2.1] - 2026-07-30&quot;">​</a></h2><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>Profile auto-select on recovery</strong> — when multiple profiles are available, <code>egain_personalization_profile_id</code> in initialization context now wins over <code>isLastUsedInPortal</code> on the profile list</li><li><strong>Stale profile list caches</strong> — <code>ApiHelper.selectUserProfile</code> invalidates cached <code>getUserProfiles</code> responses after a successful PUT; <code>AiAgent.updateUserProfile</code> clears the portal pipeline profile cache (<code>eg_profiles_*</code>) and invalidates <code>getUserProfiles</code> so the next pipeline run refetches fresh <code>isLastUsedInPortal</code> flags</li></ul><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>Portal initialization, context management, and caching guides: profile auto-select priority and profile-list cache invalidation on select / <code>updateUserProfile</code></li></ul><h2 id="_0-2-0-2026-07-29" tabindex="-1">[0.2.0] - 2026-07-29 <a class="header-anchor" href="#_0-2-0-2026-07-29" aria-label="Permalink to &quot;[0.2.0] - 2026-07-29&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><code>AiAgent.initialize(options?)</code> — optional <code>{ context }</code> merged with <code>AiAgentConfig.context</code>; stored via <code>setContext</code> for reconnect</li><li><strong>Portal/profile auto-select</strong> during <code>PortalInitializer</code> when initialization context includes <code>egain_portal_id</code> and/or <code>egain_personalization_profile_id</code> (eGain attribute <code>{ value }</code> or plain string values)</li><li>Exported type <code>AiAgentInitializeOptions</code></li><li><code>ApiHelper.getPortals()</code> — customer self-service portal list (<code>GET .../portalmgr/v3/portals</code>) with Flow A intersection against <code>agentDetails.portals</code> (replaces synthetic-only customer portal lists)</li><li><strong>Data masking</strong> — when <code>agentDetails.enableDataMasking</code> is true and the deployment version supports it, loads chat masking patterns during init and masks outbound <code>customer</code> / <code>human</code> messages in <code>send()</code>; <code>AiAgent.maskContent()</code> for UI/escalation</li><li><code>semver</code> dependency for platform version gating (cc-widget parity)</li></ul><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Customer agents with configured KB portals use tenant portal catalog + bot intersection (same rules as CC Flow A) instead of placeholder portal names only</li></ul><h3 id="documentation-1" tabindex="-1">Documentation <a class="header-anchor" href="#documentation-1" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>Portal initialization and context management guides: initialization context and auto-select behavior</li><li>Message flow guide: data masking (<code>maskContent</code>, outbound <code>send()</code> behavior)</li></ul><h2 id="_0-1-5-2026-07-27" tabindex="-1">[0.1.5] - 2026-07-27 <a class="header-anchor" href="#_0-1-5-2026-07-27" aria-label="Permalink to &quot;[0.1.5] - 2026-07-27&quot;">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><code>InitializationPipelineError</code> and <code>InitializationPipelineErrorCode</code> (<code>AUTH_TOKEN_REQUIRED</code>, <code>NO_PORTALS</code>, <code>PORTAL_FETCH_FAILED</code>, <code>PORTAL_DETAILS_FAILED</code>, <code>PROFILE_FETCH_FAILED</code>, <code>PROFILE_PERSIST_FAILED</code>, <code>NO_AGENTS_FOR_PORTAL</code>, <code>DEPARTMENT_ID_REQUIRED</code>, <code>INVALID_SELECTION</code>) — thrown when the CC portal pipeline fails; catch via <code>instanceof InitializationPipelineError</code> and branch on <code>pipelineCode</code> / <code>error.code</code></li><li><code>InitializationPipelineStage</code> on thrown errors (<code>stage</code> property) plus optional <code>portal</code> / <code>agent</code> context</li></ul><h3 id="fixed-3" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-3" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>CC pipeline failures after <code>start()</code> or after <code>selectPortal()</code> / <code>selectAgent()</code> / <code>selectUserProfile()</code> were logged internally but not surfaced to consumers; hosts can <code>await</code> those calls and catch <code>InitializationPipelineError</code> instead of staying in a loading state</li></ul><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><code>selectPortal()</code>, <code>selectAgent()</code>, and <code>selectUserProfile()</code> return <code>Promise&lt;void&gt;</code> and reject with <code>InitializationPipelineError</code> on pipeline failure</li><li><code>AiAgent</code> awaits <code>portalInitializer.start()</code> during CC init so auto-select failures reject <code>initialize()</code> when the pipeline fails before the first user gate</li><li><code>getPortalDetails</code> API failures throw <code>PORTAL_DETAILS_FAILED</code> instead of being swallowed</li></ul><h2 id="_0-1-4-2026-07-20" tabindex="-1">[0.1.4] - 2026-07-20 <a class="header-anchor" href="#_0-1-4-2026-07-20" aria-label="Permalink to &quot;[0.1.4] - 2026-07-20&quot;">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><code>HookContract.getAccessToken()</code> — async method that returns a fresh token, refreshing if expired. Connectors that need a guaranteed valid token for API calls should prefer this over the sync <code>getMsalAccessToken()</code></li></ul><h3 id="changed-4" tabindex="-1">Changed <a class="header-anchor" href="#changed-4" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Platform connector script loads for any set <code>initParams.platform</code> when <code>agentType</code> is <code>contact-center</code>, including <strong><code>standalone</code></strong> and <strong><code>test</code></strong> (cc-widget parity). <code>test</code> resolves to the standalone connector URL</li><li><code>HookContract.getMsalAccessToken()</code> is <strong>synchronous</strong> and returns the cached auth token (<code>AuthenticationService.getCachedToken()</code>), matching cc-widget connectors that do not <code>await</code></li><li><code>HookContract.getUserId()</code> returns the authenticated <strong>user/customer details</strong> <code>id</code> (from <code>getUserDetails</code> / <code>getCustomerDetails</code>), not <code>initParams.userid</code></li></ul><h3 id="fixed-4" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-4" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Skip fetching user/customer details when the agent is not authenticated (<code>agentDetails.isAuthenticated</code> is false), avoiding unnecessary <code>getUserDetails</code> / <code>getCustomerDetails</code> API calls</li></ul><h2 id="_0-1-3-2026-07-14" tabindex="-1">[0.1.3] - 2026-07-14 <a class="header-anchor" href="#_0-1-3-2026-07-14" aria-label="Permalink to &quot;[0.1.3] - 2026-07-14&quot;">​</a></h2><h3 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><code>HookContract.getQueryParams()</code> — legacy alias for <code>getInitParams()</code>, restoring compatibility with platform connectors (e.g. Genesys) that still call <code>getQueryParams()</code> after the queryParam → initParam rename</li></ul><h2 id="_0-1-2-2026-06-04" tabindex="-1">[0.1.2] - 2026-06-04 <a class="header-anchor" href="#_0-1-2-2026-06-04" aria-label="Permalink to &quot;[0.1.2] - 2026-06-04&quot;">​</a></h2><h3 id="documentation-2" tabindex="-1">Documentation <a class="header-anchor" href="#documentation-2" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>Added instructions for generating an access token (PKCE flow) as a prerequisite for the pre-auth authentication option, including required OAuth scopes (<code>core.aiservices.read</code>, <code>knowledge.portalmgr.manage</code>, <code>core.customermgr.read</code>)</li><li>Updated README, Quick Start guide, and Authentication guide</li></ul><h2 id="_0-1-0-2026-04-30-0-1-1-2026-05-01" tabindex="-1">[0.1.0] - 2026-04-30 &amp; [0.1.1] - 2026-05-01 <a class="header-anchor" href="#_0-1-0-2026-04-30-0-1-1-2026-05-01" aria-label="Permalink to &quot;[0.1.0] - 2026-04-30 &amp; [0.1.1] - 2026-05-01&quot;">​</a></h2><h3 id="first-beta-release-of-the-ai-agent-sdk" tabindex="-1">First beta release of the AI Agent SDK <a class="header-anchor" href="#first-beta-release-of-the-ai-agent-sdk" aria-label="Permalink to &quot;First beta release of the AI Agent SDK&quot;">​</a></h3><h2 id="_0-0-13-0-0-14-2026-04-xx" tabindex="-1">[0.0.13] &amp; [0.0.14] - 2026-04-XX <a class="header-anchor" href="#_0-0-13-0-0-14-2026-04-xx" aria-label="Permalink to &quot;[0.0.13] &amp; [0.0.14] - 2026-04-XX&quot;">​</a></h2><h3 id="changed-5" tabindex="-1">Changed <a class="header-anchor" href="#changed-5" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>README documentation links</li></ul><h2 id="_0-0-12-2026-04-xx" tabindex="-1">[0.0.12] - 2026-04-XX <a class="header-anchor" href="#_0-0-12-2026-04-xx" aria-label="Permalink to &quot;[0.0.12] - 2026-04-XX&quot;">​</a></h2><h3 id="added-5" tabindex="-1">Added <a class="header-anchor" href="#added-5" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Contact center (CC) <strong>portal initialization</strong> flow: chained REST pipeline (portals → optional agents → user profiles) before WebSocket connect, aligned with cc-widget behavior</li><li><strong>Platform script loading</strong> for CC connectors (e.g. Genesys, Amazon Connect): loads connector script and wires <code>PlatformComponentService</code> / <code>HookContract</code></li><li>New <code>AiAgent</code> methods: <code>selectPortal()</code>, <code>selectAgent()</code>, <code>selectUserProfile()</code>, <code>getInitParams()</code>, <code>getIsInitialized()</code>, <code>restartPortalInitializer()</code>, <code>updateUserProfile()</code>, <code>getUserDetails()</code>, <code>getCallTranscript()</code>, <code>getCallerInfo()</code>, <code>getConversationId()</code>, <code>clearCallTranscript()</code></li><li>New <code>ApiHelper</code> methods: <code>getMyPortals()</code>, <code>getAgentsByPortal()</code>, <code>getUserProfiles()</code>, <code>selectUserProfile()</code>, <code>getUserDetails()</code>, <code>getCustomerDetails()</code></li><li><code>getToken</code> callback on <code>ApiHelperConfig</code> so API calls can omit per-method <code>authToken</code> when a token provider is configured</li><li>New <code>AiAgentConfig</code> options: <code>initParams</code>, <code>scopes</code>, <code>platformScriptUrl</code>, <code>authScheme</code> (<code>popup</code> | <code>redirect</code> for auto-built PKCE)</li><li>New events: <code>initialized</code> (expanded payload), <code>portalsAvailable</code>, <code>agentsAvailable</code>, <code>profilesAvailable</code>, <code>callTranscriptUpdate</code>, <code>callerInfoUpdate</code>, <code>conversationIdUpdate</code>, <code>userContextUpdate</code>, <code>filterTagsUpdate</code></li><li>Exported types for CC and connectors: <code>Portal</code>, <code>UserProfile</code>, <code>AgentListItem</code>, <code>UserDetails</code>, <code>HookContract</code>, <code>CallerInfo</code>, <code>CallTranscriptEntry</code>, <code>PlatformComponentService</code>, and new <code>Get*</code> / <code>Select*</code> API option types</li></ul><h3 id="changed-6" tabindex="-1">Changed <a class="header-anchor" href="#changed-6" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>PKCE: <code>localLogin</code> on <code>PKCEAuthConfig</code>, improved redirect/popup behavior, <code>domain_hint</code> / <code>localLogin</code> extra query parameters, and MSAL options aligned with CC flows</li><li>Several <code>ApiHelper</code> option types now allow optional <code>authToken</code> when <code>getToken</code> is set on <code>ApiHelperConfig</code></li></ul><h3 id="deprecated" tabindex="-1">Deprecated <a class="header-anchor" href="#deprecated" aria-label="Permalink to &quot;Deprecated&quot;">​</a></h3><ul><li><code>restartCcWidgetInitializer()</code> — use <code>restartPortalInitializer()</code> instead</li></ul><h2 id="_0-0-11-2025-01-xx" tabindex="-1">[0.0.11] - 2025-01-XX <a class="header-anchor" href="#_0-0-11-2025-01-xx" aria-label="Permalink to &quot;[0.0.11] - 2025-01-XX&quot;">​</a></h2><h3 id="added-6" tabindex="-1">Added <a class="header-anchor" href="#added-6" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Browser UMD build support with <code>./browser</code> export</li><li>Browser build script (<code>build:browser</code>) for standalone browser bundle</li><li>MSAL copy script for browser compatibility</li><li>Comprehensive build pipeline with <code>build:all</code> command</li><li>Documentation generation scripts (<code>docs:api</code>, <code>docs:build</code>, <code>docs:dev</code>)</li><li>Publishing scripts for GitHub Packages</li></ul><h3 id="changed-7" tabindex="-1">Changed <a class="header-anchor" href="#changed-7" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Updated build process to include browser bundle generation</li><li>Enhanced package exports to support both Node.js and browser environments</li><li>Improved build scripts organization</li></ul><h2 id="_0-0-10-2025-01-xx" tabindex="-1">[0.0.10] - 2025-01-XX <a class="header-anchor" href="#_0-0-10-2025-01-xx" aria-label="Permalink to &quot;[0.0.10] - 2025-01-XX&quot;">​</a></h2><h3 id="added-7" tabindex="-1">Added <a class="header-anchor" href="#added-7" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Browser build configuration</li><li>Rollup bundler integration for browser builds</li><li>Browser-specific exports in package.json</li></ul><h3 id="changed-8" tabindex="-1">Changed <a class="header-anchor" href="#changed-8" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Build process now generates both Node.js and browser bundles</li></ul><h2 id="_0-0-9-2025-01-09" tabindex="-1">[0.0.9] - 2025-01-09 <a class="header-anchor" href="#_0-0-9-2025-01-09" aria-label="Permalink to &quot;[0.0.9] - 2025-01-09&quot;">​</a></h2><h3 id="added-8" tabindex="-1">Added <a class="header-anchor" href="#added-8" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><code>transcriptUpdate</code> event - emitted whenever the transcript is updated (message sent or received) <ul><li>Provides <code>TranscriptEntry</code> with message, direction, timestamp, sessionId, and agentId</li><li>Useful for tracking all message activity in real-time</li></ul></li><li>GitHub Actions workflow for automated SDK documentation deployment</li></ul><h3 id="changed-9" tabindex="-1">Changed <a class="header-anchor" href="#changed-9" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Improved VitePress documentation site structure</li><li>Moved docs folder for better organization</li></ul><h2 id="_0-0-8-2025-01-08" tabindex="-1">[0.0.8] - 2025-01-08 <a class="header-anchor" href="#_0-0-8-2025-01-08" aria-label="Permalink to &quot;[0.0.8] - 2025-01-08&quot;">​</a></h2><h3 id="changed-10" tabindex="-1">Changed <a class="header-anchor" href="#changed-10" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Removed empty content attribute from message payload</li><li>Added 5ms delay in queue flushing for improved reliability</li><li>Cached anonymous token for better performance</li><li>Added partial initialization when agent details are fetched before init</li></ul><h3 id="fixed-5" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-5" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Fixed test browser UMD build</li></ul><h2 id="_0-0-7-2025-01-08" tabindex="-1">[0.0.7] - 2025-01-08 <a class="header-anchor" href="#_0-0-7-2025-01-08" aria-label="Permalink to &quot;[0.0.7] - 2025-01-08&quot;">​</a></h2><h3 id="added-9" tabindex="-1">Added <a class="header-anchor" href="#added-9" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>VitePress documentation site</li><li>Enhanced JSDoc comments throughout the codebase</li><li>TypeDoc configuration for API reference generation</li><li>Context persistence with automatic restoration on reconnect</li><li>Custom cache adapter support</li><li><code>tokenExpiring</code> event for proactive token refresh</li><li><code>updateAccessToken()</code> method for runtime token updates</li></ul><h3 id="changed-11" tabindex="-1">Changed <a class="header-anchor" href="#changed-11" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Improved error messages for better debugging</li><li>Enhanced TypeScript type definitions</li><li>Updated documentation to use <code>pre-auth</code> instead of deprecated <code>token</code> auth type</li></ul><h3 id="fixed-6" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-6" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Various bug fixes and stability improvements</li></ul><h2 id="_0-0-6-2025-01-06" tabindex="-1">[0.0.6] - 2025-01-06 <a class="header-anchor" href="#_0-0-6-2025-01-06" aria-label="Permalink to &quot;[0.0.6] - 2025-01-06&quot;">​</a></h2><h3 id="added-10" tabindex="-1">Added <a class="header-anchor" href="#added-10" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><code>restartConnection()</code> method for fresh sessions</li><li>Automatic context caching and restoration</li><li><code>getContext()</code> and <code>removeContext()</code> methods</li><li>Transcript filtering options</li></ul><h3 id="changed-12" tabindex="-1">Changed <a class="header-anchor" href="#changed-12" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Improved reconnection logic with exponential backoff</li></ul><h2 id="_0-0-5-2025-01-03" tabindex="-1">[0.0.5] - 2025-01-03 <a class="header-anchor" href="#_0-0-5-2025-01-03" aria-label="Permalink to &quot;[0.0.5] - 2025-01-03&quot;">​</a></h2><h3 id="added-11" tabindex="-1">Added <a class="header-anchor" href="#added-11" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><code>ApiHelper</code> class for REST API interactions</li><li>Caching for API responses</li><li><code>getAgentDetails()</code> and <code>getDeploymentInfo()</code> methods</li></ul><h3 id="changed-13" tabindex="-1">Changed <a class="header-anchor" href="#changed-13" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Refactored authentication to use <code>AuthenticationService</code></li></ul><h2 id="_0-0-4-2024-12-20" tabindex="-1">[0.0.4] - 2024-12-20 <a class="header-anchor" href="#_0-0-4-2024-12-20" aria-label="Permalink to &quot;[0.0.4] - 2024-12-20&quot;">​</a></h2><h3 id="added-12" tabindex="-1">Added <a class="header-anchor" href="#added-12" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Multiple authentication strategies (Anonymous, PKCE, Pre-Auth, Client Credentials)</li><li>Message type helpers (<code>createContextMessage</code>, <code>createFeedbackMessage</code>, etc.)</li><li>Transcript management with filtering</li></ul><h2 id="_0-0-3-2024-12-15" tabindex="-1">[0.0.3] - 2024-12-15 <a class="header-anchor" href="#_0-0-3-2024-12-15" aria-label="Permalink to &quot;[0.0.3] - 2024-12-15&quot;">​</a></h2><h3 id="added-13" tabindex="-1">Added <a class="header-anchor" href="#added-13" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Message queuing when offline</li><li>Automatic queue flushing on reconnect</li><li><code>queueFlushed</code> event</li></ul><h2 id="_0-0-2-2024-12-10" tabindex="-1">[0.0.2] - 2024-12-10 <a class="header-anchor" href="#_0-0-2-2024-12-10" aria-label="Permalink to &quot;[0.0.2] - 2024-12-10&quot;">​</a></h2><h3 id="added-14" tabindex="-1">Added <a class="header-anchor" href="#added-14" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>WebSocket connection management</li><li>Automatic reconnection with exponential backoff</li><li>Event-driven architecture</li><li>TypeScript type definitions</li></ul><h2 id="_0-0-1-2024-12-01" tabindex="-1">[0.0.1] - 2024-12-01 <a class="header-anchor" href="#_0-0-1-2024-12-01" aria-label="Permalink to &quot;[0.0.1] - 2024-12-01&quot;">​</a></h2><h3 id="added-15" tabindex="-1">Added <a class="header-anchor" href="#added-15" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Initial release</li><li>Basic WebSocket communication</li><li>Pre-auth token authentication</li><li>Message sending and receiving</li></ul>',108)])])}const p=o(d,[["render",n]]);export{g as __pageData,p as default};
